Complete example (cart calculation with 3 items)
using System;
using MathLibrary;

public class ShoppingCartExample
{
    public class CartItem
    {
        public string Name { get; set; }
        public double UnitPrice { get; set; }
        public int Quantity { get; set; }
        public double DiscountPercent { get; set; }
    }

    public static void Main()
    {
        var items = new[]
        {
            new CartItem { Name = "T-Shirt", UnitPrice = 20.00, Quantity = 2, DiscountPercent = 10 },  // 10% off
            new CartItem { Name = "Jeans",   UnitPrice = 50.00, Quantity = 1, DiscountPercent = 25 },  // 25% off
            new CartItem { Name = "Socks",   UnitPrice = 5.00,  Quantity = 4, DiscountPercent = 0 }    // no discount
        };

        double taxPercent = 8.25;

        double discountedSubtotal = 0;

        foreach (var item in items)
        {
            double lineSubtotal = item.UnitPrice * item.Quantity;
            double lineAfterDiscount = PercentageCalculations.CalculateDiscountedPrice(lineSubtotal, item.DiscountPercent);

            Console.WriteLine(item.Name + ": subtotal=" + lineSubtotal + ", discount%=" + item.DiscountPercent + ", afterDiscount=" + lineAfterDiscount);

            discountedSubtotal += lineAfterDiscount;
        }

        double totalWithTax = PercentageCalculations.CalculatePriceWithTax(discountedSubtotal, taxPercent);

        Console.WriteLine("Discounted subtotal: " + discountedSubtotal);
        Console.WriteLine("Tax %: " + taxPercent);
        Console.WriteLine("Total with tax: " + totalWithTax);
    }
}

